/* メモ: スクロール時のナビ表示、動画と字幕、事例カード/詳細ダイアログ、表示アニメーションと数値カウントを制御します。 */
(function(){
var nav=document.getElementById("nav");
function showNav(){nav.classList.add("show")}
var heroEl=document.querySelector(".hero");
function navCheck(){var past=scrollY>heroEl.offsetHeight*.8;nav.classList.toggle("show",past)}
addEventListener("scroll",navCheck,{passive:true});navCheck();

var hv=document.getElementById("hv");
var pl=hv.play();if(pl&&pl.catch)pl.catch(function(){});

var uv=document.getElementById("uv"),ct=document.getElementById("ct"),cn=document.getElementById("cn"),dots=document.querySelectorAll(".dots i");
var caps=["ジムの一角に、Bridge。","QRで、その場で解錠。","運動のあと、すぐに無料で体験。","気になったら、近くのサロンへ。"],cur=-1;
function setCap(i){if(i===cur)return;cur=i;ct.style.opacity=0;setTimeout(function(){ct.textContent=caps[i];cn.textContent="STEP "+(i+1);ct.style.opacity=1},200);dots.forEach(function(d,k){d.classList.toggle("on",k===i)})}
uv.addEventListener("timeupdate",function(){var d=uv.duration||10;setCap(Math.min(3,Math.floor(uv.currentTime/(d/4))))});
new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){var p=uv.play();if(p&&p.catch)p.catch(function(){})}else uv.pause()})},{threshold:.45}).observe(uv);
new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){var p=hv.play();if(p&&p.catch)p.catch(function(){})}else hv.pause()})},{threshold:.1}).observe(hv);


/* ===== WORKS（事例）: ここに1件ずつ追加するだけ =====
 title:タイトル / tag:カテゴリ / year:年 / summary:カード用の一言 / detail:詳細 /
 image:画像のURL(任意) / video:動画のURL(任意) / link:外部リンク(任意) */
var WORKS=[
 {title:"Bridge",tag:"体験型レンタルボックス",year:"2025–",summary:"ジムの空きスペースに置く無人の体験ボックス。",fit:"top",detail:"QRで解錠し、運動後すぐに機器を試せる無人レンタルボックス。体験データをメーカーへ、悩みに合うお客様を地域サロンへつなぎます。2026年にPoCを開始予定です。",image:(document.querySelector(".pimg img")||{}).src},
 {title:"ビジネスコンテスト トップ10",tag:"受賞",year:"2023",summary:"ビジネスコンテストでトップ10に選出。",detail:"ごみ箱探索アプリ「ぽいする」の構想で、ビジネスコンテストのトップ10に選ばれました。ここで受けた数々の指摘が、のちのBridgeへの転換につながっています。",image:(document.querySelectorAll(".photos img")[2]||{}).src},
 {title:"ぽいする",tag:"アプリ開発",year:"2023",summary:"ごみ箱探索ポイ活アプリ。ユーザーの声から開発。",fit:"contain",detail:"街のごみ箱を探せて、ポイ活もできるアプリを共同開発しました。ユーザーの意見をもとに実際にアプリを作り上げた、Step Buddyの最初のプロダクトです。",image:"data:image/jpeg;base64,"},
 {title:"Soln",tag:"レンタル事業",year:"2024",summary:"髭剃りレンタルサービス。",detail:"髭剃りのレンタルサービスとして着手した事業。レンタル市場に挑んだこの経験が、体験型のBridgeにつながっています。",image:"soln 画像.png"}
];
(function(){
 var list=document.getElementById("wlist"),dlg=document.getElementById("wd");
 WORKS.forEach(function(w){
  var b=document.createElement("button");b.className="wc rv "+(list.children.length%2?"fr":"fl");b.type="button";
  var m=media(w);
  b.innerHTML='<div class="wm"></div><div class="wb"><small></small><h3></h3><p></p></div>';
  b.querySelector(".wm").appendChild(m);
  b.querySelector("small").textContent=w.tag+(w.year?" ／ "+w.year:"");
  b.querySelector("h3").textContent=w.title;b.querySelector(".wb p").textContent=w.summary||"";
  b.addEventListener("click",function(){open(w)});
  list.appendChild(b);
 });
 function media(w){
  if(w.video){var v=document.createElement("video");v.src=w.video;v.muted=true;v.loop=true;v.autoplay=true;v.playsInline=true;return v}
  if(w.image){var i=document.createElement("img");i.src=w.image;i.alt=w.title;if(w.fit)i.dataset.fit=w.fit;return i}
  return document.createTextNode(w.title.slice(0,2));
 }
 function open(w){
  var box=document.getElementById("wdm");box.innerHTML="";box.appendChild(media(w));
  document.getElementById("wdt").textContent=w.tag+(w.year?" ／ "+w.year:"");
  document.getElementById("wdh").textContent=w.title;
  document.getElementById("wdp").textContent=w.detail||w.summary||"";
  var l=document.getElementById("wdl");l.innerHTML="";
  if(w.link){var a=document.createElement("a");a.href=w.link;a.target="_blank";a.rel="noopener";a.textContent="詳しく見る →";l.appendChild(a)}
  dlg.showModal();
 }
 document.getElementById("wdx").addEventListener("click",function(){dlg.close()});
 dlg.addEventListener("click",function(e){if(e.target===dlg)dlg.close()});
})();
function count(el){var t=+el.dataset.n,d=+(el.dataset.d||0),st=null;
 function f(ts){if(!st)st=ts;var p=Math.min((ts-st)/1500,1);el.textContent=(t*(1-Math.pow(1-p,3))).toFixed(d);if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)}
var io=new IntersectionObserver(function(es){es.forEach(function(e){if(!e.isIntersecting)return;var t=e.target;t.classList.add("on");
 t.querySelectorAll("[data-n]").forEach(count);io.unobserve(t)})},{threshold:.2});
document.querySelectorAll(".rv").forEach(function(e,i){e.style.transitionDelay=(i%3)*80+"ms";io.observe(e)});
})();
